#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int longestFibonacciSubarray(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) return 0;
        int max_len = 0;
        int cur_len = 2;
        for (int i = 2; i < n; ++i) {
            if (nums[i] == nums[i - 1] + nums[i - 2]) {
                cur_len++;
                max_len = max(max_len, cur_len);
            } else {
                cur_len = 2;
            }
        }
        return max_len >= 3 ? max_len : 0;
    }
};

class Solution {
    public int longestFibonacciSubarray(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0;
        int maxLen = 0;
        int curLen = 2;
        for (int i = 2; i < n; i++) {
            if (nums[i] == nums[i - 1] + nums[i - 2]) {
                curLen++;
                maxLen = Math.max(maxLen, curLen);
            } else {
                curLen = 2;
            }
        }
        return maxLen >= 3 ? maxLen : 0;
    }
}

var longestFibonacciSubarray = function(nums) {
    const n = nums.length;
    if (n < 3) return 0;
    let maxLen = 0;
    let curLen = 2;
    for (let i = 2; i < n; i++) {
        if (nums[i] === nums[i - 1] + nums[i - 2]) {
            curLen++;
            maxLen = Math.max(maxLen, curLen);
        } else {
            curLen = 2;
        }
    }
    return maxLen >= 3 ? maxLen : 0;
};
